document.addEventListener('keydown',e=>{if(!document.getElementById('vw').hidden)return;if(!root.classList.contains('present'))return;if(e.key==='Escape')setPres(false);if((e.key==='ArrowRight'||e.key==='ArrowLeft')&&!/INPUT|SELECT|TEXTAREA|BUTTON/.test(e.target.tagName)){const i=navBtns.findIndex(b=>b.dataset.tab===curTab),n=navBtns[(i+(e.key==='ArrowRight'?1:-1)+navBtns.length)%navBtns.length];showTab(n.dataset.tab,1)}});
$('#bkExport').onclick=()=>{const imgs={};Object.keys(memImg||{}).forEach(k=>{if(safeKey(k)&&okSrc(memImg[k]))imgs[k]=memImg[k]});try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k.startsWith('bioclass:img:')&&safeKey(k.slice(13))){const v=okSrc(localStorage.getItem(k));if(v)imgs[k.slice(13)]=v}}}catch(e){}const n=Object.keys(imgs).length;if(!n){$('#bkMsg').textContent='No images to export yet.';return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({app:'bioclass',version:1,images:imgs})],{type:'application/json'}));a.download='bioclass-images.json';document.body.appendChild(a);a.click();a.remove();$('#bkMsg').textContent='Exported '+n+' image'+(n>1?'s':'')+'.'};
$('#bkImport').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(d.app!=='bioclass'||typeof d.images!=='object')throw 0;let c=0;Object.entries(d.images).forEach(([k,v])=>{if(safeKey(k)&&okUrl(v)){setImg(k,v);c++}});renderKingdoms();renderSys();$('#bkMsg').textContent='Imported '+c+' image'+(c===1?'':'s')+'.'}catch(x){$('#bkMsg').textContent='That file is not a valid BIOCLASS backup.'}};r.readAsText(f);e.target.value=''};

function collectImgs(){const imgs={};Object.keys(memImg||{}).forEach(k=>{if(safeKey(k)&&okSrc(memImg[k]))imgs[k]=memImg[k]});try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k.startsWith('bioclass:img:')&&safeKey(k.slice(13))){const v=okSrc(localStorage.getItem(k));if(v)imgs[k.slice(13)]=v}}}catch(e){}return imgs}
$('#bkSnap').onclick=async()=>{const imgs=collectImgs(),n=Object.keys(imgs).length,data={id:Date.now(),savedAt:new Date().toISOString(),images:imgs,state:{tab:curTab,sys:sysI,k:activeKingdom,o:organismSelect.value,m:sysMode,pa:phyA,pb:phyB},theme};
const O='<scr'+'ipt',C='</scr'+'ipt>';let html=SRC.replace(new RegExp(O+' id="snap"[\\s\\S]*?'+C+'\\s*'),''),inl=false;
try{const[cs,js]=await Promise.all(['style.css','app.js'].map(u=>fetch(u).then(r=>{if(!r.ok)throw 0;return r.text()})));if(cs&&js&&!/<\/scr(?=ipt)/i.test(js)){html=html.replace(/<link rel="stylesheet" href="style\.css">/,()=>'<style>\n'+cs+'</style>').replace(new RegExp(O+' src="app\\.js">'+C),()=>O+'>\n'+js+C);inl=true}}catch(e){}
const json=JSON.stringify(data).replace(/</g,'\\u003c');let at=html.indexOf(O+' src="app.js"');if(at<0)at=html.indexOf(O+'>');
if(at<0){$('#bkMsg').textContent='Could not build the snapshot.';return}
html=html.slice(0,at)+O+' id="snap" type="application/json">'+json+C+'\n'+html.slice(at);
const d=new Date(),pad=x=>String(x).padStart(2,'0'),name='diverticus-regnatrix-snapshot-'+d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())+'-'+pad(d.getHours())+pad(d.getMinutes())+'.html';
try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([html],{type:'text/html'}));a.download=name;document.body.appendChild(a);a.click();a.remove();$('#bkMsg').textContent='Snapshot saved as '+name+' ('+n+' image'+(n===1?'':'s')+', '+Math.round(html.length/1024)+' KB).'+(inl?' It works on its own.':' Keep it in the same folder as app.js and style.css.')}catch(e){$('#bkMsg').textContent='Your browser blocked the download.'}};

function pathSet(){const s=new Set();if(!keyPath||!keyPath.length)return s;s.add('Living organisms');keyPath.forEach(st=>{const y=st[1],at=st[2];if(at==='start')s.add(y?'Eukaryotes':'Monera');else if(at==='euk')s.add(y?'Multicellular':'Protista');else if(at==='uni'){s.delete('Protista');s.add(y?'Fungi':'Protista')}else if(at==='multi'){if(!y)s.add('Animalia')}else if(at==='wall')s.add(y?'Plantae':'Fungi')});return s}
const editBtn=$('#editBtn');editBtn.onclick=()=>{editMode=!editMode;root.classList.toggle('editing',editMode);editBtn.setAttribute('aria-pressed',editMode);renderSys()};

const exNice=k=>k.startsWith('ex:')?k.split(':').slice(2).join(':')+' · '+k.split(':')[1]:k;
var migrated=false;function migrateImgs(){if(migrated)return;migrated=true;try{Object.keys(localStorage).forEach(x=>{const m=/^bioclass:img:ex:[^:]+:(.+)$/.exec(x);if(!m||!organisms[m[1]])return;const ok='bioclass:img:org:'+m[1];if(!localStorage.getItem(ok))localStorage.setItem(ok,localStorage.getItem(x));localStorage.removeItem(x)})}catch(e){}}
function exDefaults(g,t){migrateImgs();const names=Object.keys(organisms);let m={};try{m=GMAP[t||systems[sysI].t]||{}}catch(e){}const si=systems.findIndex(x=>x.t===(t||systems[sysI].t));if(m[g]&&si>=0){const l=names.filter(n=>{const pg=place(n,si)[0];return pg===g||/ or /.test(pg)&&pg.split(' or ').includes(g)});if(l.length)return l}return g==='Bacteria'?names.filter(n=>organisms[n].kingdom==='Monera'):g==='Eukarya'?names.filter(n=>organisms[n].kingdom!=='Monera'):g==='Archaea'?[]:names.filter(n=>organisms[n].kingdom===g)}
function shy(t){return t.replace(/Thermoacidophiles/g,'Thermo\u00adacido\u00adphiles').replace(/Methanogens/g,'Methano\u00adgens').replace(/Halophiles/g,'Halo\u00adphiles').replace(/Chlamydomonas/g,'Chlamydo\u00admonas').replace(/Cyanobacterium/g,'Cyano\u00adbacterium').replace(/oxidising/g,'oxi\u00addising')}
function exRow(g){const imgs=collectImgs(),pre='ex:'+g+':',custom=Object.keys(imgs).filter(k=>k.startsWith(pre)).map(k=>k.slice(pre.length)),list=[...new Set([...exDefaults(g),...custom])];
const tiles=list.map(n=>{const k=pre+n,im=getImg(k);return`<div class="extile" data-ex="${esc(k)}" tabindex="0" role="button" aria-label="${esc(n)} example image"><div class="exbox${im?' has':''}">${im?`<img src="${im.replace(/"/g,'')}" alt="" referrerpolicy="no-referrer">`:'<b>+</b>'}</div><span>${shy(esc(n))}</span></div>`}).join('');
return`<div class="exhead">EXAMPLES <i>double-tap to view · hold 6 s to edit</i></div><div class="exrow">${tiles}<div class="extile add" data-add="${g}" tabindex="0" role="button" aria-label="Add an example to ${g}"><div class="exbox"><b>+</b></div><span>Add</span></div></div>`}
var edNew=false,edG='';
function addEx(g){if(!ed.hidden||!document.getElementById('vw').hidden)return;edNew=true;edG=g;edK='';pend='';document.getElementById('edT').textContent='Add example to '+g;document.getElementById('edName').hidden=false;document.getElementById('edName').value='';document.getElementById('edUrl').value='';prevEd();ed.hidden=false}
document.addEventListener('click',e=>{const a=e.target.closest('.extile.add');if(a&&!held){addEx(a.dataset.add);return}const t=e.target.closest('.extile[data-ex]');if(t&&!held&&editMode)editImg(t.dataset.ex)});
document.addEventListener('keydown',e=>{const t=e.target.closest&&e.target.closest('.extile');if(t&&(e.key==='Enter'||e.key===' ')){e.preventDefault();t.dataset.add?addEx(t.dataset.add):editMode?editImg(t.dataset.ex):openViewer(t)}else if(t&&!t.dataset.add&&(e.key==='e'||e.key==='E'))editImg(t.dataset.ex)});

var HOLD=6000;
const keyOf=el=>el.dataset.k||el.dataset.ik||el.dataset.ex;
function gestEl(e){return e.target.closest&&e.target.closest('.imgslot,.extile[data-ex]')}
let gest=null,lastTap=null,ring=null,ringRaf=0;
function startRing(el){endRing();const r=el.getBoundingClientRect(),t0=Date.now();ring=document.createElement('div');ring.className='hring';ring.style.left=(r.left+r.width/2)+'px';ring.style.top=(r.top+r.height/2)+'px';ring.hidden=true;document.body.appendChild(ring);
(function tick(){if(!ring)return;const el_=Date.now()-t0;if(el_>500)ring.hidden=false;ring.style.setProperty('--p',Math.min(100,el_/HOLD*100));ringRaf=requestAnimationFrame(tick)})()}
function endRing(){cancelAnimationFrame(ringRaf);if(ring){ring.remove();ring=null}}
document.addEventListener('pointerdown',e=>{const el=gestEl(e);if(!el)return;stopHold();held=false;gest={key:keyOf(el),el,x:e.clientX,y:e.clientY};startRing(el);holdT=setTimeout(()=>{held=true;endRing();editImg(keyOf(el))},HOLD)});
document.addEventListener('pointermove',e=>{if(gest&&!gest.moved&&Math.hypot(e.clientX-gest.x,e.clientY-gest.y)>12){gest.moved=true;stopHold();endRing()}});
document.addEventListener('pointerup',e=>{stopHold();endRing();const g=gest;gest=null;if(!g||held||g.moved)return;const now=Date.now();if(lastTap&&lastTap.key===g.key&&now-lastTap.t<350){lastTap=null;openViewer(g.el)}else lastTap={key:g.key,t:now}});
document.addEventListener('touchend',()=>{stopHold();endRing()});
document.addEventListener('scroll',endRing,true);
document.body.insertAdjacentHTML('beforeend','<div class="vw" id="vw" hidden><div class="vcard" id="vcard" role="dialog" aria-modal="true" aria-label="Picture viewer"><button class="vx" id="vx" aria-label="Close">✕</button><div class="vimg" id="vimg"></div><div class="vcap"><b id="vname"></b><span id="vsub"></span><p id="vtxt"></p></div><div class="vnav"><button id="vprev" aria-label="Previous">‹</button><span id="vpos"></span><button id="vnext" aria-label="Next">›</button></div><button class="vsel" id="vsel" hidden>Show details</button></div></div>');
const vw=document.getElementById('vw'),vcard=document.getElementById('vcard');let vItems=[],vI=0,vOpener=null,vAt=0;
const INNER={'Living organisms':'All living things.','Eukaryotes':'Organisms whose cells have a membrane-bound nucleus.','Multicellular':'Organisms whose bodies are made of many cells.'};
function itemInfo(el){const key=keyOf(el);
if(el.dataset.ex){const p=key.split(':'),name=p.slice(2).join(':'),o=organisms[name];return{key,name,sub:(sci[name]?sci[name]+' · ':'')+p[1],txt:o?o.reason:'',g:''}}
const gn=systems[sysI].n.find(m=>m[0]===key);return{key,name:key,sub:systems[sysI].t,txt:gn?gn[1]+'.':INNER[key]||'',g:el.dataset.g||(el.classList.contains('imgslot')?key:'')}}
function listFor(el){if(el.dataset.ex)return[...el.closest('.exrow').querySelectorAll('.extile[data-ex]')];const sv=el.closest('svg');if(sv){const all=[...sv.querySelectorAll('.tn[data-ik]:not(.ghost)')].sort((a,b)=>a.dataset.o-b.dataset.o);return all.includes(el)?all:[el]}return[el]}
function showV(dir){const it=vItems[vI],im=getImg(it.key);document.getElementById('vimg').innerHTML=im?`<img src="${im.replace(/"/g,'')}" alt="" referrerpolicy="no-referrer">`:'<p>No picture yet. Press and hold the box for 6 seconds to add one.</p>';
document.getElementById('vname').textContent=it.name;document.getElementById('vsub').textContent=it.sub;document.getElementById('vtxt').textContent=it.txt;document.getElementById('vpos').textContent=(vI+1)+' / '+vItems.length;
document.getElementById('vprev').disabled=vI===0;document.getElementById('vnext').disabled=vI===vItems.length-1;const sb=document.getElementById('vsel');sb.hidden=!it.g;
vcard.style.transform='';vcard.style.opacity='';vcard.classList.remove('in-l','in-r','in-u');void vcard.offsetWidth;vcard.classList.add(dir>0?'in-r':dir<0?'in-l':'in-u')}
let pulsing=null;
function pulseTo(el,done){const sv=el.ownerSVGElement,d=el.dataset.trail,L=+el.dataset.len||0;if(pulsing||!sv||!d||!L||matchMedia('(prefers-reduced-motion: reduce)').matches){if(!pulsing)done();return}
const NS='http://www.w3.org/2000/svg',mk=(c)=>{const p=document.createElementNS(NS,'path');p.setAttribute('d',d);p.setAttribute('class',c);sv.insertBefore(p,sv.querySelector('.tn'));return p},glow=mk('pulse glow'),core=mk('pulse');
const dur=Math.min(760,Math.max(460,L*1.7)),HEAD=44,stops=(el.dataset.stops||'').split(',').filter(Boolean).map(z=>z.split(':')),lit=[];let t0=0;pulsing={el};
const fin=()=>{glow.remove();core.remove();el.classList.add('arrive');setTimeout(()=>{el.classList.remove('arrive');lit.forEach(x=>x.classList.remove('lit'));pulsing=null;done()},170)};
const step=ts=>{if(!t0)t0=ts;const k=Math.min(1,(ts-t0)/dur),e=1-Math.pow(1-k,2),pos=e*(L+HEAD);[glow,core].forEach(p=>{p.style.strokeDasharray=HEAD+' '+(L+HEAD*4);p.style.strokeDashoffset=String(HEAD-pos)});
stops.forEach(sp=>{if(!sp.done&&pos>=+sp[0]){sp.done=1;sv.querySelectorAll('[data-m="'+sp[1]+'"]').forEach(x=>{x.classList.add('lit');lit.push(x)})}});if(k<1)requestAnimationFrame(step);else fin()};requestAnimationFrame(step)}
function openGallery(g,opener){if(!ed.hidden||!vw.hidden)return;const pre='ex:'+g+':',imgs=collectImgs(),names=[...new Set([...exDefaults(g),...Object.keys(imgs).filter(k=>k.startsWith(pre)).map(k=>k.slice(pre.length))])],keys=names.map(n=>pre+n).filter(k=>getImg(k));
if(!keys.length){openSheet(g);const h=document.querySelector('#ks .exhead');if(h&&!document.querySelector('#ks .exnote'))h.insertAdjacentHTML('afterend','<p class="exnote">No pictures yet. Hold an example below for 6 seconds to add one.</p>');return}
vItems=keys.map(k=>itemInfo({dataset:{ex:k},classList:{contains:()=>false}}));vI=0;vOpener=opener;vAt=Date.now();vw.hidden=false;showV(0);document.getElementById('vx').focus()}
function openViewer(el){if(!ed.hidden)return;const els=listFor(el);vItems=els.map(itemInfo);vI=Math.max(0,els.indexOf(el));vOpener=el;vAt=Date.now();vw.hidden=false;showV(0);document.getElementById('vx').focus()}
function closeV(){if(vw.hidden)return;vw.hidden=true;if(vOpener&&vOpener.isConnected)try{vOpener.focus()}catch(e){}}
function stepV(d){const n=vI+d;if(n<0||n>=vItems.length)return false;vI=n;showV(d);return true}
document.getElementById('vx').onclick=closeV;document.getElementById('vprev').onclick=()=>stepV(-1);document.getElementById('vnext').onclick=()=>stepV(1);
document.getElementById('vsel').onclick=()=>{const g=vItems[vI].g;if(g){activeKingdom=g;closeV();renderSys()}};
vw.addEventListener('click',e=>{if(Date.now()-vAt<450){e.stopPropagation();e.preventDefault()}},true);vw.addEventListener('click',e=>{if(e.target===vw&&Date.now()-vAt>450)closeV()});
let vs=null;vcard.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;vs={x:e.clientX,y:e.clientY,dx:0,dy:0}});
vcard.addEventListener('pointermove',e=>{if(!vs)return;vs.dx=e.clientX-vs.x;vs.dy=e.clientY-vs.y;if(Math.abs(vs.dx)>Math.abs(vs.dy)){vcard.style.transform=`translateX(${vs.dx}px) rotate(${vs.dx/40}deg)`;vcard.style.opacity=1-Math.min(.5,Math.abs(vs.dx)/400)}else if(vs.dy>0){vcard.style.transform=`translateY(${vs.dy}px)`}});
vcard.addEventListener('pointerup',()=>{if(!vs)return;const{dx,dy}=vs;vs=null;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)){if(!stepV(dx<0?1:-1)){vcard.style.transform='';vcard.style.opacity=''}}else if(dy>90)closeV();else{vcard.style.transform='';vcard.style.opacity=''}});
vcard.addEventListener('pointercancel',()=>{vs=null;vcard.style.transform='';vcard.style.opacity=''});
document.addEventListener('keydown',e=>{if(vw.hidden)return;if(e.key==='Escape')closeV();else if(e.key==='ArrowRight')stepV(1);else if(e.key==='ArrowLeft')stepV(-1)},true);

const timeBtn=$('#timeBtn');timeBtn.onclick=()=>{journeyOn=!journeyOn;timeBtn.setAttribute('aria-pressed',journeyOn);if(journeyOn){showTab('systems');$('#journey').scrollIntoView({behavior:'smooth',block:'start'})}else showTab(curTab)};

['pointerdown','keydown','click','change','input'].forEach(n=>document.addEventListener(n,()=>{userActed=true},true));

document.addEventListener('error',e=>{const t=e.target;if(!t||!t.tagName||!/^(img|image)$/i.test(t.tagName))return;const src=t.getAttribute('src')||t.getAttribute('href')||'';if(!src||badImg.has(src))return;badImg.add(src);try{renderSys()}catch(x){}if(!document.getElementById('vw').hidden)try{showV(0)}catch(x){}},true);
